css:
.kawaii-pass,
.kawaii-pass__avatar,
.kawaii-pass__face,
.kawaii-pass__eye,
.kawaii-pass__brow,
.kawaii-pass__mouth,
.kawaii-pass__blush,
.kawaii-pass__tear,
.kawaii-pass__sparkle,
.kawaii-pass__input {
  box-sizing: border-box;
}

.kawaii-pass {
  --kp-ink: #1a1a1a;
  --kp-cream: #fff7e8;
  --kp-green: #a8e6a0;
  --kp-hot-green: #4dd865;
  --kp-mint: #7ee8c9;
  --kp-lavender: #c8b6ff;
  --kp-yellow: #ffe066;
  --kp-red: #ff6b6b;

  position: relative;
  display: flex;
  align-items: center;
  gap: 1.125em;
  width: min(28.75em, 100%);
  padding: 1.375em;
  border-radius: 1.625em;
  border: 0.1875em solid var(--kp-ink);
  background: linear-gradient(135deg, #fff7e8 0%, #e8f5e8 100%);
  box-shadow:
    0.5em 0.5em 0 var(--kp-ink),
    0 1.375em 2.8125em -1.375em rgba(0, 0, 0, 0.35);
  font-size: 12px;
  font-family:
    ui-rounded,
    "SF Pro Rounded",
    system-ui,
    -apple-system,
    "Segoe UI",
    Roboto,
    sans-serif;
  transition:
    box-shadow 0.3s ease,
    transform 0.3s ease;
}

.kawaii-pass:hover {
  transform: translate(0.125em, 0.125em);
  box-shadow:
    0.375em 0.375em 0 var(--kp-ink),
    0 1.25em 2.5em -1.375em rgba(0, 0, 0, 0.35);
}

.kawaii-pass:has(.kawaii-pass__input:focus) {
  transform: translate(0.1875em, 0.1875em);
  box-shadow:
    0.3125em 0.3125em 0 var(--kp-ink),
    0 1.125em 2.1875em -1.25em rgba(0, 0, 0, 0.35);
}

.kawaii-pass__avatar {
  position: relative;
  flex: 0 0 5.25em;
  width: 5.25em;
  height: 5.25em;
  display: grid;
  place-items: center;
}

.kawaii-pass__face {
  position: relative;
  width: 4.75em;
  height: 4.75em;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #fff0b0 0%, #d6f5d6 80%);
  border: 0.1875em solid var(--kp-ink);
  box-shadow: 0.25em 0.25em 0 var(--kp-ink);
  transition:
    background 0.4s ease,
    box-shadow 0.4s ease,
    transform 0.45s cubic-bezier(0.34, 1.56, 0.64, 1);
  overflow: visible;
}

.kawaii-pass__eye {
  position: absolute;
  top: 1.875em;
  width: 0.875em;
  height: 0.875em;
  border-radius: 50%;
  background: var(--kp-ink);
  transition:
    top 0.35s cubic-bezier(0.34, 1.56, 0.64, 1),
    width 0.35s cubic-bezier(0.34, 1.56, 0.64, 1),
    height 0.35s cubic-bezier(0.34, 1.56, 0.64, 1),
    border-radius 0.35s ease,
    background 0.35s ease;
}

.kawaii-pass__eye--l {
  left: 0.875em;
}
.kawaii-pass__eye--r {
  right: 0.875em;
}

.kawaii-pass__eye::after {
  content: "";
  position: absolute;
  top: 0.1875em;
  left: 0.1875em;
  width: 0.3125em;
  height: 0.3125em;
  border-radius: 50%;
  background: #fff;
  transition: all 0.3s ease;
}

.kawaii-pass__brow {
  position: absolute;
  top: 1.375em;
  width: 0.875em;
  height: 0.1875em;
  border-radius: 0.1875em;
  background: var(--kp-ink);
  transition: all 0.35s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.kawaii-pass__brow--l {
  left: 0.75em;
}
.kawaii-pass__brow--r {
  right: 0.75em;
}

.kawaii-pass__mouth {
  position: absolute;
  left: 50%;
  bottom: 1em;
  width: 1em;
  height: 0.25em;
  background: var(--kp-ink);
  border-radius: 0.25em;
  transform: translateX(-50%);
  transition:
    bottom 0.35s cubic-bezier(0.34, 1.56, 0.64, 1),
    width 0.35s cubic-bezier(0.34, 1.56, 0.64, 1),
    height 0.35s cubic-bezier(0.34, 1.56, 0.64, 1),
    border-radius 0.35s ease,
    background 0.35s ease;
}

.kawaii-pass__blush {
  position: absolute;
  top: 2.75em;
  width: 0.75em;
  height: 0.5em;
  border-radius: 50%;
  background: var(--kp-hot-green);
  opacity: 0.55;
  filter: blur(0.5px);
  transition: all 0.35s ease;
}

.kawaii-pass__blush--l {
  left: 0.25em;
}
.kawaii-pass__blush--r {
  right: 0.25em;
}

.kawaii-pass__tear {
  position: absolute;
  top: 2.625em;
  left: 0.9375em;
  width: 0.5em;
  height: 0.75em;
  background: var(--kp-red);
  border: 0.125em solid var(--kp-ink);
  border-radius: 50% 50% 50% 50% / 65% 65% 35% 35%;
  opacity: 0;
  transform: translateY(-0.5em) scale(0.6);
  transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.kawaii-pass__sparkle {
  position: absolute;
  width: 0.875em;
  height: 0.875em;
  background: var(--kp-yellow);
  clip-path: polygon(
    50% 0%,
    61% 35%,
    100% 50%,
    61% 65%,
    50% 100%,
    39% 65%,
    0% 50%,
    39% 35%
  );
  opacity: 0;
  z-index: 2;
  pointer-events: none;
}

.kawaii-pass__sparkle--1 {
  top: -0.5em;
  right: -0.25em;
  background: var(--kp-yellow);
}
.kawaii-pass__sparkle--2 {
  top: 0.25em;
  left: -0.625em;
  background: var(--kp-hot-green);
}
.kawaii-pass__sparkle--3 {
  bottom: -0.375em;
  right: 0.375em;
  background: var(--kp-mint);
}
.kawaii-pass__sparkle--4 {
  top: 2.375em;
  right: -0.75em;
  background: var(--kp-lavender);
}

.kawaii-pass__field {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5em;
}

.kawaii-pass__input {
  width: 100%;
  height: 3.25em;
  padding: 0 1em;
  border: 0.1875em solid var(--kp-ink);
  border-radius: 1em;
  background: #fff;
  color: var(--kp-ink);
  font-family: inherit;
  font-size: 1em;
  font-weight: 700;
  letter-spacing: 0.14em;
  outline: none;
  box-shadow: 0.25em 0.25em 0 var(--kp-ink);
  transition: all 0.3s ease;
}

.kawaii-pass__input::selection {
  background: var(--kp-yellow);
  color: var(--kp-ink);
}

.kawaii-pass__input:hover:not(:focus):not(:active) {
  transform: translate(0.0625em, 0.0625em);
  background: #fffdf5;
  box-shadow: 0.1875em 0.1875em 0 var(--kp-ink);
}

.kawaii-pass__input:active {
  transform: translate(0.125em, 0.125em);
  box-shadow: 0.125em 0.125em 0 var(--kp-ink);
}

.kawaii-pass__input:focus {
  transform: translate(0.125em, 0.125em);
  box-shadow: 0.125em 0.125em 0 var(--kp-ink);
  background: #fffdf5;
}

.kawaii-pass__label {
  position: absolute;
  left: 1.125em;
  top: 1.625em;
  transform: translateY(-50%);
  font-size: 0.9375em;
  font-weight: 800;
  color: #a1a1a1;
  pointer-events: none;
  transition: all 0.28s ease;
}

.kawaii-pass:has(.kawaii-pass__input:focus) .kawaii-pass__label,
.kawaii-pass:has(.kawaii-pass__input:not(:placeholder-shown))
  .kawaii-pass__label {
  opacity: 0;
  transform: translateY(-50%) translateX(0.625em);
}

.kawaii-pass__hint {
  display: block;
  min-height: 1em;
  padding-left: 0.375em;
  font-size: 0.78em;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: #a1a1a1;
  transition: color 0.35s ease;
}

.kawaii-pass__hint::after {
  content: "Say the magic word…";
}

.kawaii-pass:has(.kawaii-pass__input:focus) .kawaii-pass__face {
  transform: scale(1.05);
}

.kawaii-pass:has(.kawaii-pass__input:focus) .kawaii-pass__hint {
  color: var(--kp-hot-green);
}

.kawaii-pass:has(.kawaii-pass__input:focus) .kawaii-pass__hint::after {
  content: "I'm listening… 👀";
}

.kawaii-pass:has(.kawaii-pass__input:invalid:not(:placeholder-shown))
  .kawaii-pass__face {
  background: radial-gradient(circle at 35% 30%, #ffd6d6 0%, #ff8a8a 80%);
  transform: scale(0.96);
  animation: kawaii-pass-sad-shake 2.4s ease-in-out infinite;
}

.kawaii-pass:has(.kawaii-pass__input:invalid:not(:placeholder-shown))
  .kawaii-pass__brow {
  top: 1.25em;
}
.kawaii-pass:has(.kawaii-pass__input:invalid:not(:placeholder-shown))
  .kawaii-pass__brow--l {
  transform: rotate(-24deg);
}
.kawaii-pass:has(.kawaii-pass__input:invalid:not(:placeholder-shown))
  .kawaii-pass__brow--r {
  transform: rotate(24deg);
}

.kawaii-pass:has(.kawaii-pass__input:invalid:not(:placeholder-shown))
  .kawaii-pass__eye {
  top: 2em;
  height: 0.6875em;
  border-radius: 50% 50% 40% 40%;
}
.kawaii-pass:has(.kawaii-pass__input:invalid:not(:placeholder-shown))
  .kawaii-pass__eye::after {
  top: 0.25em;
  left: 0.1875em;
  width: 0.25em;
  height: 0.25em;
}

.kawaii-pass:has(.kawaii-pass__input:invalid:not(:placeholder-shown))
  .kawaii-pass__mouth {
  bottom: 1.125em;
  width: 1em;
  height: 0.375em;
  background: transparent;
  border-top: 0.1875em solid var(--kp-ink);
  border-radius: 50% 50% 0 0 / 100% 100% 0 0;
}

.kawaii-pass:has(.kawaii-pass__input:invalid:not(:placeholder-shown))
  .kawaii-pass__blush {
  background: #e87b7b;
  opacity: 0.45;
}

.kawaii-pass:has(.kawaii-pass__input:invalid:not(:placeholder-shown))
  .kawaii-pass__tear {
  opacity: 1;
  animation: kawaii-pass-tear-drop 1.6s ease-in-out infinite;
}

.kawaii-pass:has(.kawaii-pass__input:invalid:not(:placeholder-shown))
  .kawaii-pass__hint {
  color: #d46b6b;
}

.kawaii-pass:has(.kawaii-pass__input:invalid:not(:placeholder-shown))
  .kawaii-pass__hint::after {
  content: "Need 8+ chars with letters & numbers…";
}

.kawaii-pass:has(.kawaii-pass__input:valid:not(:placeholder-shown))
  .kawaii-pass__face {
  background: radial-gradient(
    circle at 35% 30%,
    #ffe066 0%,
    #7ee87e 55%,
    #4dd865 100%
  );
  transform: scale(1.08);
  box-shadow:
    0.25em 0.25em 0 var(--kp-ink),
    0 0 1.625em rgba(77, 216, 101, 0.55);
  animation: kawaii-pass-happy-bounce 1.3s ease-in-out infinite;
}

.kawaii-pass:has(.kawaii-pass__input:valid:not(:placeholder-shown))
  .kawaii-pass__brow {
  top: 1.0625em;
}
.kawaii-pass:has(.kawaii-pass__input:valid:not(:placeholder-shown))
  .kawaii-pass__brow--l {
  transform: rotate(-12deg);
}
.kawaii-pass:has(.kawaii-pass__input:valid:not(:placeholder-shown))
  .kawaii-pass__brow--r {
  transform: rotate(12deg);
}

.kawaii-pass:has(.kawaii-pass__input:valid:not(:placeholder-shown))
  .kawaii-pass__eye {
  top: 1.875em;
  width: 1.0625em;
  height: 0.5625em;
  border-radius: 1.0625em 1.0625em 0.1875em 0.1875em / 1.0625em 1.0625em 0.125em
    0.125em;
  background: var(--kp-ink);
}
.kawaii-pass:has(.kawaii-pass__input:valid:not(:placeholder-shown))
  .kawaii-pass__eye::after {
  opacity: 0;
  transform: scale(0.3);
}

.kawaii-pass:has(.kawaii-pass__input:valid:not(:placeholder-shown))
  .kawaii-pass__mouth {
  bottom: 0.75em;
  width: 1.625em;
  height: 0.9375em;
  background: var(--kp-ink);
  border-radius: 0 0 1.625em 1.625em / 0 0 1.375em 1.375em;
}

.kawaii-pass:has(.kawaii-pass__input:valid:not(:placeholder-shown))
  .kawaii-pass__blush {
  opacity: 0.95;
  background: var(--kp-hot-green);
  transform: scale(1.35);
}

.kawaii-pass:has(.kawaii-pass__input:valid:not(:placeholder-shown))
  .kawaii-pass__tear {
  opacity: 0;
}

.kawaii-pass:has(.kawaii-pass__input:valid:not(:placeholder-shown))
  .kawaii-pass__sparkle {
  opacity: 1;
}
.kawaii-pass:has(.kawaii-pass__input:valid:not(:placeholder-shown))
  .kawaii-pass__sparkle--1 {
  animation: kawaii-pass-twinkle 1.1s ease-in-out infinite;
}
.kawaii-pass:has(.kawaii-pass__input:valid:not(:placeholder-shown))
  .kawaii-pass__sparkle--2 {
  animation: kawaii-pass-twinkle 1.1s ease-in-out 0.28s infinite;
}
.kawaii-pass:has(.kawaii-pass__input:valid:not(:placeholder-shown))
  .kawaii-pass__sparkle--3 {
  animation: kawaii-pass-twinkle 1.1s ease-in-out 0.56s infinite;
}
.kawaii-pass:has(.kawaii-pass__input:valid:not(:placeholder-shown))
  .kawaii-pass__sparkle--4 {
  animation: kawaii-pass-twinkle 1.1s ease-in-out 0.84s infinite;
}

.kawaii-pass:has(.kawaii-pass__input:valid:not(:placeholder-shown))
  .kawaii-pass__input {
  background: #fffbe0;
  box-shadow:
    0.125em 0.125em 0 var(--kp-ink),
    0 0 0 0.1875em rgba(255, 224, 102, 0.55);
}

.kawaii-pass:has(.kawaii-pass__input:valid:not(:placeholder-shown))
  .kawaii-pass__hint {
  color: var(--kp-hot-green);
}

.kawaii-pass:has(.kawaii-pass__input:valid:not(:placeholder-shown))
  .kawaii-pass__hint::after {
  content: "Yay! Super strong password!";
}

@keyframes kawaii-pass-sad-shake {
  0%,
  100% {
    transform: scale(0.96) rotate(0deg);
  }
  25% {
    transform: scale(0.96) rotate(-2.5deg);
  }
  75% {
    transform: scale(0.96) rotate(2.5deg);
  }
}

@keyframes kawaii-pass-happy-bounce {
  0%,
  100% {
    transform: scale(1.08) translateY(0) rotate(-4deg);
  }
  50% {
    transform: scale(1.14) translateY(-0.42em) rotate(4deg);
  }
}

@keyframes kawaii-pass-tear-drop {
  0% {
    transform: translateY(-0.5em) scale(0.7);
    opacity: 0;
  }
  25% {
    transform: translateY(0) scale(1);
    opacity: 1;
  }
  75% {
    transform: translateY(0.5em) scale(1);
    opacity: 1;
  }
  100% {
    transform: translateY(1.167em) scale(0.5);
    opacity: 0;
  }
}

@keyframes kawaii-pass-twinkle {
  0%,
  100% {
    transform: scale(0.6) rotate(0deg);
    opacity: 0.55;
  }
  50% {
    transform: scale(1.3) rotate(45deg);
    opacity: 1;
  }
}
